package com.gk.jobhelper.service;

import com.gk.jobhelper.common.*;import com.gk.jobhelper.entity.RecruitmentAttachment;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.regex.*;import org.jsoup.Jsoup;import org.jsoup.nodes.*;import org.slf4j.*;import org.springframework.stereotype.Service;
@Service public class RecruitmentAttachmentDownloadService {private static final Logger log=LoggerFactory.getLogger(RecruitmentAttachmentDownloadService.class);private static final int MAX=20*1024*1024,MAX_HOPS=3;private final RecruitmentFileTypeDetector detector;private String relayMethod;public RecruitmentAttachmentDownloadService(RecruitmentFileTypeDetector d){detector=d;}
 public DownloadedAttachment download(RecruitmentAttachment a){try{String original=a.getFileUrl(),current=original,referer=null;Map<String,String> cookies=new LinkedHashMap<>();int redirects=0,relays=0;for(int hop=0;hop<=MAX_HOPS;hop++){Response response=request(current,referer,cookies);if(redirect(response.status)){if(++redirects>MAX_HOPS)throw fail("岗位附件重定向次数超过限制");String location=response.header("Location");if(location==null)throw fail("岗位附件重定向缺少地址");referer=current;current=resolve(current,location);continue;}if(response.status<200||response.status>=300)throw fail("岗位附件下载失败，HTTP "+response.status);String type=detector.detect(response.contentType,a.getFileName(),response.bytes);if(!"HTML".equals(type))return result(a,original,current,redirects,relays,response,type);String html=new String(response.bytes,StandardCharsets.UTF_8);if(externalSourceRestricted(current,html))throw fail("附件来源需要安全验证，暂时无法自动解析，可前往原文查看。");if(++relays>MAX_HOPS)throw fail("岗位附件中转页层级超过限制");String next=relayUrl(html,current);if(next==null)throw fail("未在HTML中转页找到真实文件下载地址");log.info("招聘附件中转页：attachmentId={}, method={}, relayUrl={}",a.getId(),relayMethod,next);referer=current;current=next;}throw fail("岗位附件中转链路超过限制");}catch(BusinessException e){throw e;}catch(Exception e){log.warn("招聘附件下载失败，url={}, type={}, message={}",a.getFileUrl(),e.getClass().getSimpleName(),e.getMessage());throw fail("岗位附件下载失败，请稍后重试");}}
 private DownloadedAttachment result(RecruitmentAttachment a,String original,String current,int redirects,int relays,Response r,String type){String disposition=r.header("Content-Disposition"),name=fileName(disposition,a.getFileName());log.info("招聘附件下载完成：attachmentId={}, originalUrl={}, finalUrl={}, status={}, contentType={}, contentDisposition={}, bytes={}, redirects={}, relays={}, fileType={}",a.getId(),original,current,r.status,r.contentType,disposition,r.bytes.length,redirects,relays,type);return new DownloadedAttachment(a.getId(),name,r.contentType,type,r.bytes,original,current,r.status,disposition,redirects,relays);}
 private Response request(String url,String referer,Map<String,String> cookies)throws IOException{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(30000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Mozilla/5.0");if(referer!=null)c.setRequestProperty("Referer",referer);if(!cookies.isEmpty())c.setRequestProperty("Cookie",cookieLine(cookies));int status=c.getResponseCode();cookies(c,cookies);if(c.getContentLength()>MAX)throw fail("岗位附件超过20MB限制");InputStream in=status>=400?c.getErrorStream():c.getInputStream();return new Response(status,c.getContentType(),c.getHeaderFields(),in==null?new byte[0]:read(in));}
 private String relayUrl(String html,String base){Document doc=Jsoup.parse(html,base);for(Element e:doc.select("a[href],form[action],iframe[src],[data-url],[data-href],[data-file]")){String value=first(e,"href","action","src","data-url","data-href","data-file");if(candidate(e.text(),value)){relayMethod=e.hasAttr("href")?"a[href]":e.hasAttr("action")?"form[action]":e.hasAttr("src")?"iframe[src]":"data-url";return resolve(base,value);}}Matcher m=Pattern.compile("(?:location(?:\\.href)?|window\\.open)\\s*(?:=|\\()\\s*['\"]([^'\"]+)['\"]",Pattern.CASE_INSENSITIVE).matcher(html);while(m.find())if(candidate("",m.group(1))){relayMethod="script";return resolve(base,m.group(1));}return null;}
 private boolean candidate(String text,String value){String all=(text+" "+value).toLowerCase(Locale.ROOT);return value!=null&&!value.startsWith("javascript:")&&!value.startsWith("#")&&(all.contains("download")||all.contains("attachment")||all.contains("file")||all.contains("附件")||all.contains("下载")||all.matches(".*\\.(xlsx?|docx?|pdf|zip)(?:[?#].*)?"));}private boolean externalSourceRestricted(String url,String html){String value=(url+" "+html).toLowerCase(Locale.ROOT);return value.contains("mp.weixin.qq.com")&&(value.contains("tcaptcha")||value.contains("verifyresult")||value.contains("安全验证"));}private String first(Element e,String... names){for(String name:names)if(e.hasAttr(name)&&!e.attr(name).trim().isEmpty())return e.attr(name).trim();return null;}private String resolve(String base,String relative){return URI.create(base).resolve(relative).normalize().toString();}private boolean redirect(int s){return s==301||s==302||s==303||s==307||s==308;}
 private void cookies(HttpURLConnection c,Map<String,String> jar){for(Map.Entry<String,List<String>> header:c.getHeaderFields().entrySet())if(header.getKey()!=null&&"Set-Cookie".equalsIgnoreCase(header.getKey()))for(String value:header.getValue()){int end=value.indexOf(';'),split=value.indexOf('=');if(split>0)jar.put(value.substring(0,split),value.substring(split+1,end<0?value.length():end));}}private String cookieLine(Map<String,String> jar){StringBuilder out=new StringBuilder();for(Map.Entry<String,String> e:jar.entrySet()){if(out.length()>0)out.append("; ");out.append(e.getKey()).append('=').append(e.getValue());}return out.toString();}private String fileName(String d,String fallback){if(d==null)return fallback;Matcher m=Pattern.compile("filename\\*?=(?:UTF-8''|\\\")?([^;\\\"]+)",Pattern.CASE_INSENSITIVE).matcher(d);try{return m.find()?URLDecoder.decode(m.group(1).trim(),"UTF-8"):fallback;}catch(Exception ignored){return fallback;}}private byte[] read(InputStream input)throws IOException{try(InputStream in=input;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n,total=0;while((n=in.read(b))!=-1){total+=n;if(total>MAX)throw fail("岗位附件超过20MB限制");out.write(b,0,n);}return out.toByteArray();}}private BusinessException fail(String message){return new BusinessException(ApiResponse.CODE_BAD_REQUEST,message);}private static class Response{final int status;final String contentType;final Map<String,List<String>> headers;final byte[] bytes;Response(int s,String c,Map<String,List<String>> h,byte[] b){status=s;contentType=c;headers=h;bytes=b;}String header(String name){for(Map.Entry<String,List<String>> e:headers.entrySet())if(e.getKey()!=null&&name.equalsIgnoreCase(e.getKey())&&!e.getValue().isEmpty())return e.getValue().get(0);return null;}}}
